import{_ as a,o as e,c as o,a3 as r}from"./chunks/framework.DMtjdCb-.js";const s="/help/assets/first-login.ja.Bkgpi-3g.png",i="/help/assets/connections.ja.C1-7BJvL.png",n="/help/assets/connect-ani-rss.ja.C3842EcY.png",u=JSON.parse('{"title":"3. 初回ログイン","description":"","frontmatter":{},"headers":[],"relativePath":"ja/first-use.md","filePath":"ja/first-use.md"}'),l={name:"ja/first-use.md"};function c(p,t,d,h,g,_){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="_3-初回ログイン" tabindex="-1">3. 初回ログイン <a class="header-anchor" href="#_3-初回ログイン" aria-label="Permalink to &quot;3. 初回ログイン&quot;">​</a></h1><p>ログインし、作品を表示できることと動画の保存先を確認します。</p><h2 id="ログインする" tabindex="-1">ログインする <a class="header-anchor" href="#ログインする" aria-label="Permalink to &quot;ログインする&quot;">​</a></h2><ol><li>起動ウィンドウまたはコンテナーログのアドレスを開きます。</li><li>そこに表示された初期ユーザー名とランダムパスワードで <strong>ログイン</strong> します。</li><li>アカウント情報を保存します。PC 版では <code>data/state/auth/initial-admin.txt</code> にも記録されています。</li></ol><p><img src="'+s+'" alt="初回ログイン：起動ウィンドウやログのアカウントを使用" loading="lazy"></p><p><strong>設定 → ユーザー</strong> で別のアカウントを作成できます。視聴記録と非表示の作品はアカウントごとに保存されるため、家族も個別の記録を使用できます。</p><p>各アカウントは自分のパスワードを変更できます。管理者は <strong>設定 → ユーザー → パスワードを変更</strong>、そのほかのユーザーは <strong>設定</strong> を開きます。現在のパスワードと新しいパスワードを確認用も含めて入力します。この端末はログインを維持し、ほかの端末では新しいパスワードで再ログインします。初期パスワードを変更すると、古い初期認証情報のファイルも削除されます。</p><h2 id="作品情報の準備を待つ" tabindex="-1">作品情報の準備を待つ <a class="header-anchor" href="#作品情報の準備を待つ" aria-label="Permalink to &quot;作品情報の準備を待つ&quot;">​</a></h2><p>初回は Bangumi Archive を取得・検証し、今期と最近の作品から準備します。残りはバックグラウンドで補完します。ホームの状態欄に現在の段階が表示され、同梱の今期画像は作品の準備後に利用できます。</p><p>作品が表示されたら、検索・購読・再生を先に利用できます。過去の作品、コレクション整理、ローカルダウンロード計画は、全体の資料が揃ってから順次利用できます。中断した場合も同じフォルダーから起動すると再開します。</p><p><strong>確認する画面：</strong> 作品カードが表示され、クリックすると詳細が開きます。残りの画像取得中も表示済みの作品を利用できます。</p><h2 id="サービス接続を確認する" tabindex="-1">サービス接続を確認する <a class="header-anchor" href="#サービス接続を確認する" aria-label="Permalink to &quot;サービス接続を確認する&quot;">​</a></h2><p><strong>設定 → 接続</strong> で Ani-RSS と qBittorrent を確認します。</p><p><img src="'+i+'" alt="フル構成の接続状態：各サービスの準備を確認" loading="lazy"></p><p><img src="'+n+'" alt="Ani-RSS：自動設定された接続先と動画フォルダー" loading="lazy"></p><ul><li><strong>標準 NAS 構成：</strong> 自動接続を待ちます。キーの手入力は不要です。</li><li><strong>PC 版・既存サービス：</strong> アドレスと認証情報を入力し、接続をテストして保存します。</li><li><strong>手持ちの動画だけを見る：</strong> <a href="./collections.html">コレクションを追加</a>し、ダウンロード用サービスは必要になってから接続できます。</li></ul><p><strong>デプロイ設定</strong> と表示された項目は起動設定から読み込まれ、現在の有効な値が表示されます。標準構成ではそのまま使用できます。既存のサービスに接続する場合は、対応する構成テンプレートでアドレスを指定します。</p><p>ブラウザーは <code>http://NASのアドレス:ポート</code> を開きます。標準構成内の <code>http://ani-rss:7789</code>、<code>http://qbittorrent:8080</code> はコンテナー同士が接続するためのアドレスです。</p><h2 id="保存先を確認する" tabindex="-1">保存先を確認する <a class="header-anchor" href="#保存先を確認する" aria-label="Permalink to &quot;保存先を確認する&quot;">​</a></h2><p>標準構成には <code>/Library</code>、<code>/Media</code> などが設定されています。まずはそのまま使えます。別のディスクを使用する場合は、<a href="./collections.html">既存のコレクション</a>で NAS とコンテナーのパスの対応を確認してから変更します。</p><p>続いて<a href="./subscribe.html">作品を購読</a>し、最初のダウンロードを確認します。</p>',21)])])}const f=a(l,[["render",c]]);export{u as __pageData,f as default};
